/* BrightAI OCR Demo — Gemini 2.5 Flash Vision | brightai.site */
(function () {
  'use strict';

  const GEMINI_API_KEY = 'AIzaSyBFMmyO7sgXaSbF47zd3rbO6I9MfhbYLK8';
  const GEMINI_MODEL   = 'gemini-2.5-flash';
  const GEMINI_URL     = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${GEMINI_API_KEY}`;

  const btnRun   = document.getElementById('ocr-run');
  const outEl    = document.getElementById('ocr-output');
  const jsonEl   = document.getElementById('ocr-json');
  const fileEl   = document.getElementById('ocr-file');
  const dropZone = document.querySelector('.drop-zone');

  if (!btnRun || !outEl || !jsonEl || !fileEl) return;

  const origLabel = btnRun.innerHTML;

  /* ─── حقول المستند المدعومة ─── */
  const FIELD_LABELS = {
    document_type  : 'نوع المستند',
    invoice_number : 'رقم الفاتورة',
    total_amount   : 'المبلغ الإجمالي',
    tax_amount     : 'قيمة الضريبة',
    tax_rate       : 'نسبة الضريبة',
    date           : 'التاريخ',
    due_date       : 'تاريخ الاستحقاق',
    vendor_name    : 'اسم الجهة',
    buyer_name     : 'اسم المشتري',
    currency       : 'العملة',
    vat_number     : 'الرقم الضريبي',
    cr_number      : 'السجل التجاري',
    id_number      : 'رقم الهوية',
    address        : 'العنوان',
    items_count    : 'عدد البنود',
    subtotal       : 'الإجمالي قبل الضريبة',
    payment_method : 'طريقة الدفع',
    bank_account   : 'رقم الحساب',
    notes          : 'ملاحظات'
  };

  /* ─── حالة UI ─── */
  function setLoading(on) {
    btnRun.disabled = on;
    btnRun.innerHTML = on
      ? '<i class="fa-solid fa-circle-notch fa-spin"></i> جارٍ التحليل...'
      : origLabel;
    if (on) {
      outEl.innerHTML = '<div class="ocr-processing"><i class="fa-solid fa-magnifying-glass fa-beat-fade"></i><span>جارٍ استخراج النصوص والحقول...</span></div>';
      jsonEl.textContent = 'جارٍ تجهيز JSON...';
    }
  }

  function setError(msg) {
    outEl.innerHTML = `<div class="ocr-error"><i class="fa-solid fa-triangle-exclamation"></i> ${msg}</div>`;
    jsonEl.textContent = '{}';
  }

  /* ─── رسم نتائج الحقول ─── */
  function renderFields(fields) {
    if (!fields || typeof fields !== 'object' || Object.keys(fields).length === 0) {
      outEl.innerHTML = '<div class="field-row"><span>الحالة</span><span>لم يُعثر على حقول واضحة</span></div>';
      return;
    }

    const rows = Object.entries(FIELD_LABELS)
      .filter(([key]) => fields[key] !== undefined && fields[key] !== null && fields[key] !== '')
      .map(([key, label]) => {
        const val = String(fields[key]);
        const isMonetary = ['total_amount','tax_amount','subtotal'].includes(key);
        return `<div class="field-row">
          <span class="field-label">${label}</span>
          <span class="field-value ${isMonetary ? 'monetary' : ''}">${val}</span>
        </div>`;
      });

    // أي حقول إضافية أرجعها الموديل ليست في القائمة
    Object.entries(fields).forEach(([key, val]) => {
      if (!FIELD_LABELS[key] && val) {
        rows.push(`<div class="field-row">
          <span class="field-label">${key}</span>
          <span class="field-value">${String(val)}</span>
        </div>`);
      }
    });

    if (rows.length === 0) {
      outEl.innerHTML = '<div class="field-row"><span>الحالة</span><span>لم يُعثر على حقول واضحة</span></div>';
    } else {
      outEl.innerHTML = `<div class="fields-header"><i class="fa-solid fa-check-circle" style="color:#10b981"></i> تم الاستخراج بنجاح — ${rows.length} حقل</div>` + rows.join('');
    }
  }

  function renderJSON(fields) {
    try {
      jsonEl.textContent = JSON.stringify(fields || {}, null, 2);
    } catch (_) {
      jsonEl.textContent = '{}';
    }
  }

  /* ─── تحويل الملف لـ base64 ─── */
  function toBase64(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload  = () => {
        // نزع data:...;base64, prefix
        const result = reader.result;
        const comma  = result.indexOf(',');
        resolve(comma !== -1 ? result.slice(comma + 1) : result);
      };
      reader.onerror = () => reject(new Error('READ_ERROR'));
      reader.readAsDataURL(file);
    });
  }

  /* ─── prompt استخراج الحقول ─── */
  const OCR_PROMPT = `أنت نظام OCR متخصص في المستندات العربية والإنجليزية للسوق السعودي.
حلّل الصورة/الملف المرفق واستخرج جميع الحقول المتاحة.
أعد الإجابة بـ JSON فقط — لا نص إضافي — بالمفاتيح التالية (أضف أي حقل مناسب لم يُذكر):
{
  "document_type": "نوع المستند (فاتورة / هوية / عقد / ...)",
  "invoice_number": "رقم الفاتورة إن وجد",
  "date": "التاريخ",
  "due_date": "تاريخ الاستحقاق إن وجد",
  "vendor_name": "اسم الجهة أو البائع",
  "buyer_name": "اسم المشتري إن وجد",
  "total_amount": "المبلغ الإجمالي شاملاً الضريبة",
  "subtotal": "الإجمالي قبل الضريبة",
  "tax_amount": "قيمة الضريبة",
  "tax_rate": "نسبة الضريبة",
  "currency": "العملة",
  "vat_number": "الرقم الضريبي",
  "cr_number": "رقم السجل التجاري",
  "id_number": "رقم الهوية إن وجد",
  "address": "العنوان",
  "items_count": "عدد بنود الفاتورة",
  "payment_method": "طريقة الدفع",
  "bank_account": "رقم الحساب",
  "notes": "أي ملاحظات مهمة"
}
إذا لم يكن الحقل موجوداً اتركه null. لا تخمّن.`;

  /* ─── الطلب الرئيسي ─── */
  async function runOCR() {
    const file = fileEl.files && fileEl.files[0];
    if (!file) {
      setError('يرجى اختيار ملف أولاً.');
      return;
    }

    const MAX_BYTES = 4 * 1024 * 1024; // 4MB
    if (file.size > MAX_BYTES) {
      setError('حجم الملف يتجاوز 4 ميجابايت. يرجى اختيار ملف أصغر.');
      return;
    }

    const ALLOWED = ['image/jpeg','image/png','image/webp','image/gif','application/pdf'];
    if (!ALLOWED.includes(file.type)) {
      setError('نوع الملف غير مدعوم. المقبول: PDF, PNG, JPG, WEBP.');
      return;
    }

    setLoading(true);

    try {
      const b64      = await toBase64(file);
      const mimeType = file.type === 'application/pdf' ? 'application/pdf' : file.type;

      const body = {
        contents: [{
          parts: [
            { text: OCR_PROMPT },
            { inline_data: { mime_type: mimeType, data: b64 } }
          ]
        }],
        generationConfig: {
          temperature     : 0.1,
          maxOutputTokens : 1024,
          responseMimeType: 'application/json'
        }
      };

      const res = await fetch(GEMINI_URL, {
        method  : 'POST',
        headers : { 'Content-Type': 'application/json' },
        body    : JSON.stringify(body)
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData?.error?.message || `خطأ ${res.status}`);
      }

      const data  = await res.json();
      const raw   = data?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

      // تنظيف JSON من أي backticks
      const clean = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

      let fields;
      try {
        fields = JSON.parse(clean);
      } catch (_) {
        // محاولة استخراج JSON من النص
        const match = clean.match(/\{[\s\S]*\}/);
        fields = match ? JSON.parse(match[0]) : {};
      }

      // إزالة الحقول null
      const cleaned = Object.fromEntries(
        Object.entries(fields).filter(([, v]) => v !== null && v !== undefined && v !== '')
      );

      renderFields(cleaned);
      renderJSON(cleaned);

      // تأثير نجاح
      outEl.classList.add('done-pulse');
      setTimeout(() => outEl.classList.remove('done-pulse'), 800);

    } catch (err) {
      console.error('[BrightAI OCR]', err);
      setError('تعذّر تحليل الملف. تحقق من الاتصال وحاول مرة أخرى.');
    } finally {
      setLoading(false);
    }
  }

  /* ─── أحداث ─── */
  btnRun.addEventListener('click', runOCR);

  // Drag & Drop
  if (dropZone) {
    dropZone.addEventListener('dragover', (e) => {
      e.preventDefault();
      dropZone.classList.add('drag-over');
    });
    dropZone.addEventListener('dragleave', () => dropZone.classList.remove('drag-over'));
    dropZone.addEventListener('drop', (e) => {
      e.preventDefault();
      dropZone.classList.remove('drag-over');
      const dt = e.dataTransfer;
      if (dt && dt.files.length) {
        fileEl.files = dt.files;
        _updateFileLabel(dt.files[0].name);
        runOCR();
      }
    });
  }

  // تحديث اسم الملف
  fileEl.addEventListener('change', () => {
    if (fileEl.files[0]) _updateFileLabel(fileEl.files[0].name);
  });

  function _updateFileLabel(name) {
    const label = document.getElementById('file-name-label');
    if (label) label.textContent = name;
  }

  // زر نسخ JSON
  const copyBtn = document.getElementById('copy-json');
  if (copyBtn) {
    copyBtn.addEventListener('click', () => {
      navigator.clipboard.writeText(jsonEl.textContent || '{}').then(() => {
        copyBtn.innerHTML = '<i class="fa-solid fa-check"></i> تم النسخ';
        setTimeout(() => { copyBtn.innerHTML = '<i class="fa-solid fa-copy"></i> نسخ JSON'; }, 2000);
      });
    });
  }

})();
